#include <algorithm>
#include <cstdint>
#include <cwchar>
#include <string>
#include <vector>

using DWORD = std::uint32_t;
using LONG = std::int32_t;
using BYTE = std::uint8_t;

constexpr LONG ERROR_SUCCESS = 0, ERROR_FILE_NOT_FOUND = 2, ERROR_INVALID_PARAMETER = 87,
               ERROR_MORE_DATA = 234, ERROR_NO_MORE_ITEMS = 259;
constexpr DWORD REG_NONE = 0, REG_SZ = 1, REG_BINARY = 3, REG_DWORD = 4, REG_QWORD = 11;

class ValueStore
{
public:
    LONG setValue(const wchar_t* name, DWORD type, const BYTE* data, DWORD cbData)
    {
        const std::wstring key{ name ? name : L"" };
        if (key.size() > 255) return ERROR_INVALID_PARAMETER;
        if (data == nullptr && cbData != 0) return ERROR_INVALID_PARAMETER;
        if (type == REG_DWORD && cbData != 4) return ERROR_INVALID_PARAMETER;
        if (type == REG_QWORD && cbData != 8) return ERROR_INVALID_PARAMETER;
        if (type == REG_SZ && cbData % 2 != 0) return ERROR_INVALID_PARAMETER;

        std::vector<BYTE> bytes(data, data + cbData);
        if (type == REG_SZ)
        {
            const std::size_t n{ bytes.size() };
            if (n < 2 || bytes[n - 1] != 0 || bytes[n - 2] != 0) bytes.insert(bytes.end(), { 0, 0 });
        }
        if (Value* existing{ find(key) })
        {
            existing->type = type;
            existing->data = std::move(bytes);
        }
        else
        {
            values_.push_back({ key, type, std::move(bytes) });
        }
        return ERROR_SUCCESS;
    }

    LONG queryValue(const wchar_t* name, DWORD* type, BYTE* data, DWORD* cbData) const
    {
        const Value* v{ find(name ? name : L"") };
        if (v == nullptr) return ERROR_FILE_NOT_FOUND;
        if (data != nullptr && cbData == nullptr) return ERROR_INVALID_PARAMETER;
        if (type != nullptr) *type = v->type;
        const auto size{ static_cast<DWORD>(v->data.size()) };
        if (data == nullptr)
        {
            if (cbData != nullptr) *cbData = size;
            return ERROR_SUCCESS;
        }
        if (*cbData < size)
        {
            *cbData = size;
            return ERROR_MORE_DATA;
        }
        std::copy(v->data.begin(), v->data.end(), data);
        *cbData = size;
        return ERROR_SUCCESS;
    }

    LONG deleteValue(const wchar_t* name)
    {
        const std::wstring key{ name ? name : L"" };
        const auto it{ std::find_if(values_.begin(), values_.end(), [&](const Value& v) { return same(v.name, key); }) };
        if (it == values_.end()) return ERROR_FILE_NOT_FOUND;
        values_.erase(it);
        return ERROR_SUCCESS;
    }

    LONG enumValue(DWORD index, wchar_t* name, DWORD* cchName, DWORD* type) const
    {
        if (name == nullptr || cchName == nullptr) return ERROR_INVALID_PARAMETER;
        if (index >= values_.size()) return ERROR_NO_MORE_ITEMS;
        const Value& v{ values_[index] };
        const auto needed{ static_cast<DWORD>(v.name.size() + 1) };
        if (*cchName < needed)
        {
            *cchName = needed;
            return ERROR_MORE_DATA;
        }
        std::copy(v.name.begin(), v.name.end(), name);
        name[v.name.size()] = L'\0';
        *cchName = needed - 1;
        if (type != nullptr) *type = v.type;
        return ERROR_SUCCESS;
    }

    DWORD count() const { return static_cast<DWORD>(values_.size()); }

private:
    struct Value
    {
        std::wstring name;
        DWORD type;
        std::vector<BYTE> data;
    };

    static wchar_t fold(wchar_t c) { return (c >= L'A' && c <= L'Z') ? static_cast<wchar_t>(c - L'A' + L'a') : c; }

    static bool same(const std::wstring& a, const std::wstring& b)
    {
        return a.size() == b.size() && std::equal(a.begin(), a.end(), b.begin(), [](wchar_t x, wchar_t y) { return fold(x) == fold(y); });
    }

    Value* find(const std::wstring& key)
    {
        for (Value& v : values_) if (same(v.name, key)) return &v;
        return nullptr;
    }

    const Value* find(const std::wstring& key) const
    {
        for (const Value& v : values_) if (same(v.name, key)) return &v;
        return nullptr;
    }

    std::vector<Value> values_;
};

unitTests:
#include <cstring>
#include <cwchar>
#include <string>
#include <vector>
LONG setString(ValueStore& s, const wchar_t* name, const std::wstring& text, bool withNull = true) {
    const auto bytes{ static_cast<DWORD>((text.size() + (withNull ? 1 : 0)) * sizeof(wchar_t)) };
    return s.setValue(name, REG_SZ, reinterpret_cast<const BYTE*>(text.c_str()), bytes);
}
LONG setDword(ValueStore& s, const wchar_t* name, DWORD value) {
    return s.setValue(name, REG_DWORD, reinterpret_cast<const BYTE*>(&value), 4);
}
std::wstring readString(const ValueStore& s, const wchar_t* name) {
    DWORD size{ 0 };
    if (s.queryValue(name, nullptr, nullptr, &size) != ERROR_SUCCESS) return L"<missing>";
    std::vector<BYTE> buffer(size);
    if (s.queryValue(name, nullptr, buffer.data(), &size) != ERROR_SUCCESS) return L"<failed>";
    return std::wstring(reinterpret_cast<const wchar_t*>(buffer.data()));
}
TEST("setting and reading values") {
    ValueStore s;
    CHECK_EQ(setString(s, L"Theme", L"mocha"), ERROR_SUCCESS);
    CHECK_EQ(setDword(s, L"Volume", 70), ERROR_SUCCESS);
    CHECK(readString(s, L"Theme") == L"mocha");
    DWORD type{ 99 }, value{ 0 }, size{ 4 };
    CHECK_EQ(s.queryValue(L"Volume", &type, reinterpret_cast<BYTE*>(&value), &size), ERROR_SUCCESS);
    CHECK(type == REG_DWORD && value == 70 && size == 4);
    CHECK_EQ(s.count(), 2u);
}
TEST("asking for the size first") {
    ValueStore s;
    setString(s, L"Name", L"Xenon");
    DWORD size{ 0 }, type{ 0 };
    CHECK_EQ(s.queryValue(L"Name", &type, nullptr, &size), ERROR_SUCCESS);
    CHECK(size == 12 && type == REG_SZ);
    CHECK_EQ(s.queryValue(L"Name", nullptr, nullptr, nullptr), ERROR_SUCCESS);
    BYTE small[4]{ 1, 2, 3, 4 };
    DWORD smallSize{ 4 };
    type = 0;
    CHECK_EQ(s.queryValue(L"Name", &type, small, &smallSize), ERROR_MORE_DATA);
    CHECK(smallSize == 12 && type == REG_SZ);
    CHECK(small[0] == 1 && small[3] == 4);
    BYTE buffer[4]{};
    CHECK_EQ(s.queryValue(L"Name", nullptr, buffer, nullptr), ERROR_INVALID_PARAMETER);
}
TEST("missing values") {
    ValueStore s;
    DWORD size{ 77 }, type{ 77 };
    CHECK_EQ(s.queryValue(L"Ghost", &type, nullptr, &size), ERROR_FILE_NOT_FOUND);
    CHECK(size == 77 && type == 77);
    CHECK_EQ(s.deleteValue(L"Ghost"), ERROR_FILE_NOT_FOUND);
}
TEST("checking the data") {
    ValueStore s;
    const BYTE three[3]{ 1, 2, 3 };
    CHECK_EQ(s.setValue(L"D", REG_DWORD, three, 3), ERROR_INVALID_PARAMETER);
    CHECK_EQ(s.setValue(L"Q", REG_QWORD, three, 3), ERROR_INVALID_PARAMETER);
    CHECK_EQ(s.setValue(L"S", REG_SZ, three, 3), ERROR_INVALID_PARAMETER);
    CHECK_EQ(s.setValue(L"N", REG_BINARY, nullptr, 2), ERROR_INVALID_PARAMETER);
    CHECK_EQ(s.count(), 0u);
    CHECK_EQ(s.setValue(L"B", REG_BINARY, three, 3), ERROR_SUCCESS);
    CHECK_EQ(s.setValue(L"Empty", REG_BINARY, nullptr, 0), ERROR_SUCCESS);
    DWORD size{ 9 };
    CHECK_EQ(s.queryValue(L"Empty", nullptr, nullptr, &size), ERROR_SUCCESS);
    CHECK_EQ(size, 0u);
    const std::wstring longName(256, L'x');
    CHECK_EQ(setDword(s, longName.c_str(), 1), ERROR_INVALID_PARAMETER);
    const std::wstring okName(255, L'x');
    CHECK_EQ(setDword(s, okName.c_str(), 1), ERROR_SUCCESS);
}
TEST("strings always end with a null") {
    ValueStore s;
    CHECK_EQ(setString(s, L"NoNull", L"abc", false), ERROR_SUCCESS);
    DWORD size{ 0 };
    s.queryValue(L"NoNull", nullptr, nullptr, &size);
    CHECK_EQ(size, 8u);
    CHECK(readString(s, L"NoNull") == L"abc");
    CHECK_EQ(s.setValue(L"Blank", REG_SZ, nullptr, 0), ERROR_SUCCESS);
    s.queryValue(L"Blank", nullptr, nullptr, &size);
    CHECK_EQ(size, 2u);
    setString(s, L"WithNull", L"abc");
    s.queryValue(L"WithNull", nullptr, nullptr, &size);
    CHECK_EQ(size, 8u);
}
TEST("names ignore case and keep their spelling") {
    ValueStore s;
    setDword(s, L"Volume", 1);
    setDword(s, L"VOLUME", 2);
    CHECK_EQ(s.count(), 1u);
    DWORD value{ 0 }, size{ 4 };
    s.queryValue(L"vOlUmE", nullptr, reinterpret_cast<BYTE*>(&value), &size);
    CHECK_EQ(value, 2u);
    wchar_t name[16];
    DWORD cch{ 16 };
    CHECK_EQ(s.enumValue(0, name, &cch, nullptr), ERROR_SUCCESS);
    CHECK(std::wstring(name) == L"Volume" && cch == 6);
    setDword(s, L"Été", 1);
    setDword(s, L"été", 2);
    CHECK_EQ(s.count(), 3u);
}
TEST("the default value") {
    ValueStore s;
    setString(s, nullptr, L"first");
    CHECK(readString(s, L"") == L"first");
    setString(s, L"", L"second");
    CHECK(readString(s, nullptr) == L"second");
    CHECK_EQ(s.count(), 1u);
    wchar_t name[4]{ L'?', L'?', L'?', L'?' };
    DWORD cch{ 4 };
    CHECK_EQ(s.enumValue(0, name, &cch, nullptr), ERROR_SUCCESS);
    CHECK(name[0] == L'\0' && cch == 0);
    CHECK_EQ(s.deleteValue(nullptr), ERROR_SUCCESS);
    CHECK_EQ(s.count(), 0u);
}
TEST("enumerating in order") {
    ValueStore s;
    setDword(s, L"One", 1);
    setString(s, L"Two", L"2");
    setDword(s, L"Three", 3);
    setDword(s, L"one", 11);
    wchar_t name[16];
    DWORD cch{ 16 }, type{ 0 };
    CHECK_EQ(s.enumValue(1, name, &cch, &type), ERROR_SUCCESS);
    CHECK(std::wstring(name) == L"Two" && cch == 3 && type == REG_SZ);
    cch = 16;
    CHECK_EQ(s.enumValue(0, name, &cch, &type), ERROR_SUCCESS);
    CHECK(std::wstring(name) == L"One" && type == REG_DWORD);
    cch = 16;
    CHECK_EQ(s.enumValue(3, name, &cch, nullptr), ERROR_NO_MORE_ITEMS);
    CHECK_EQ(s.deleteValue(L"TWO"), ERROR_SUCCESS);
    cch = 16;
    CHECK_EQ(s.enumValue(1, name, &cch, nullptr), ERROR_SUCCESS);
    CHECK(std::wstring(name) == L"Three");
    CHECK_EQ(s.enumValue(0, nullptr, &cch, nullptr), ERROR_INVALID_PARAMETER);
    CHECK_EQ(s.enumValue(0, name, nullptr, nullptr), ERROR_INVALID_PARAMETER);
}
TEST("a name buffer that is too small") {
    ValueStore s;
    setDword(s, L"Brightness", 5);
    wchar_t name[10];
    std::wmemset(name, L'#', 10);
    DWORD cch{ 10 };
    CHECK_EQ(s.enumValue(0, name, &cch, nullptr), ERROR_MORE_DATA);
    CHECK_EQ(cch, 11u);
    CHECK(name[0] == L'#');
    wchar_t exact[11];
    cch = 11;
    CHECK_EQ(s.enumValue(0, exact, &cch, nullptr), ERROR_SUCCESS);
    CHECK(std::wstring(exact) == L"Brightness" && cch == 10);
}

